    for(let left=weight(state)+1;;--left){assert(left>0);assert.equal(flow.getFlowDomainId(state),row.domain);const hash=flow.serializeFlowHash(state);
      assert.deepEqual(flow.parseFlowHash(hash),state);assert.deepEqual(viewer.diagramState(state.graph,hash),state);if(!weight(state))break;
      const previous=flow.backFlowState(state);assert(weight(previous)<weight(state));state=previous;}
