function coverageData(flow,techniques,references,walks,preflightPassed=true){return{techniques,references,walks,preflightPassed,isWalkValid:(row,id)=>{
  try{const value=flow.walkFromRoot(row.choices,row.entryGraphId);return flow.getGraph(row.entryGraphId).entry===true&&value.consumed===row.choices.length&&value.current.type==='result'&&candidates(value).includes(id)
    &&JSON.stringify(value.steps.map(({graph,node,answer})=>({graph,node,answer})))===JSON.stringify(row.steps);}catch{return false;}}};}
const selection=(plan,current)=>({...plan.corpora.find(row=>row.auditFile===current.audit),cutoff:plan.cutoff});
function assessed(audit,data,chosen,reviewed,covered){const result=assessCorpus(audit,data,chosen);assert.deepEqual(result.errors,[]);assert.equal(result.totalProblems,6);assert.equal(result.reviewedProblems,reviewed);assert.equal(result.coveredProblems,covered);assert.equal(result.researchComplete,reviewed===6);assert.equal(result.coverageComplete,reviewed===6&&covered===6);return result;}

test('Simurgh coverage requires its actual source, confirmed metadata, complete walk and steps while the initial4/6 research is preserved',async()=>{
  const {flow}=await implementation;const[plan,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const data=coverageData(flow,techniques,references,walks),current=cases[0],live=await json(current.audit),chosen=selection(plan,current);
  assessed(frozen.audits[current.audit],data,chosen,4,3);const actual=assessCorpus(live,data,chosen);assert.deepEqual(actual.errors,[]);const reviewed=actual.reviewedProblems,covered=actual.coveredProblems;assert(reviewed>=4&&covered>=4);assert(actual.records.find(r=>r.problemId===current.problemId).resolved);assessed(live,data,chosen,reviewed,covered);
  const noResolution=structuredClone(live);delete noResolution.records.find(row=>match(row,current)).resolution;assessed(noResolution,data,chosen,reviewed,covered-1);
  assessed(live,{...data,references:references.filter(row=>row.techniqueId!==current.id)},chosen,reviewed,covered-1);
  assessed(live,{...data,techniques:techniques.filter(row=>row.id!==current.id)},chosen,reviewed,covered-1);
  const draftMetadata=structuredClone(techniques);draftMetadata.find(row=>row.id===current.id).status='draft';
  assessed(live,{...data,techniques:draftMetadata},chosen,reviewed,covered-1);
  const noExample=walks.filter(row=>!(match(row,current)&&row.expectedTechniqueIds.includes(current.id)));
  assessed(live,coverageData(flow,techniques,references,noExample),chosen,reviewed,covered-1);
  const wrongSource=structuredClone(references);wrongSource.find(row=>row.techniqueId===current.id).url='https://example.invalid/wrong-original';assessed(live,{...data,references:wrongSource},chosen,reviewed,covered-1);
  const badWalk=structuredClone(walks);badWalk.find(row=>match(row,current)&&row.expectedTechniqueIds.includes(current.id)).choices=[...current.prefix,'no'];
  assessed(live,coverageData(flow,techniques,references,badWalk),chosen,reviewed,covered-1);
  const badSteps=structuredClone(walks);badSteps.find(row=>match(row,current)&&row.expectedTechniqueIds.includes(current.id)).steps.at(-1).answer='unknown';
  assessed(live,coverageData(flow,techniques,references,badSteps),chosen,reviewed,covered-1);
});

// A read-only mirror: source article files are symlinks, but mutations replace
// the mirror link itself before writing. No source file is opened for writing.
async function mirrorDirectory(source,destination){await mkdir(destination,{recursive:true});for(const entry of await readdir(source,{withFileTypes:true})){
  if(entry.name.startsWith('.'))continue;const from=path.join(source,entry.name),to=path.join(destination,entry.name);
  if(entry.isDirectory())await mirrorDirectory(from,to);else await symlink(from,to);}}
test('an invalid actual article C++ fence fails the real content preflight and removes production coverage',async()=>{
  const {flow}=await implementation;const[plan,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const mirror=await mkdtemp(path.join(tmpdir(),'flowchartcp-ioi2017-simurgh-preflight-'));const originals=[];
  try{await mirrorDirectory(path.join(site,'data'),path.join(mirror,'data'));await mirrorDirectory(path.join(site,'src/content/docs'),path.join(mirror,'src/content/docs'));
    for(const directory of ['public','research','vendor'])await symlink(path.join(site,directory),path.join(mirror,directory),'dir');
    const clean=await validateSite(mirror);assert.deepEqual(clean.errors,[],'unmodified isolated mirror must pass the actual preflight');
    for(const current of cases){const relative='src/content/docs/techniques/'+current.id+'.mdx',target=path.join(mirror,relative),source=await readFile(path.join(site,relative),'utf8');
      originals.push([relative,bytesHash(source)]);const broken=source.replace(/^```cpp\s*\n[\s\S]*?^```\s*$/m,'```cpp\n```');assert.notEqual(broken,source);
      await unlink(target);await writeFile(target,broken);const invalid=await validateSite(mirror);
      assert(invalid.errors.some(error=>error.includes(current.id)&&/再利用可能な実装例/.test(error)),'actual invalid fence rejected by product preflight');
      const audit=await json(current.audit),data=coverageData(flow,techniques,references,walks,invalid.errors.length===0);assessed(audit,data,selection(plan,current),assessCorpus(audit,coverageData(flow,techniques,references,walks),selection(plan,current)).reviewedProblems,0);
      await unlink(target);await symlink(path.join(site,relative),target);
    }
  }finally{await rm(mirror,{recursive:true,force:true});}
  for(const[relative,hash]of originals)assert.equal(bytesHash(await readFile(path.join(site,relative))),hash,'source MDX bytes remain unchanged');
});
